/** Opaque identifiers. Generated by infrastructure (see IdGenerator). */
export type UserId = string;
export type GroupId = string;
export type AssignmentId = string;
export type MessageId = string;

export interface User {
  id: UserId;
  name: string;
  /** Small compressed data URI or null. */
  photo: string | null;
  email: string | null;
  googleSub: string | null;
  appleSub: string | null;
  createdAt: Date;
}

export type GroupStatus = 'open' | 'drawn' | 'revealed';

export interface Member {
  userId: UserId;
  /** false when the organizer chose "solo organizo". */
  participates: boolean;
  joinedAt: Date;
  /** Whether the member already opened their assignment (no content leaks). */
  hasSeenAssignment: boolean;
}

/** An exclusion is symmetric: neither person may give to the other. */
export type Exclusion = readonly [UserId, UserId];

export interface Group {
  id: GroupId;
  name: string;
  organizerId: UserId;
  /** Delivery day (date of the party), stored as UTC midnight. */
  deliveryDate: Date;
  /** Whole Colombian pesos agreed by the group; null when not set yet. */
  budgetCop: number | null;
  photo: string | null;
  inviteCode: string;
  inviteExpiresAt: Date;
  status: GroupStatus;
  premium: boolean;
  members: Member[];
  exclusions: Exclusion[];
  /** How many draws were executed (1 = first draw). Visible to everyone. */
  drawCount: number;
  drawnAt: Date | null;
  revealedAt: Date | null;
  createdAt: Date;
  /** Optimistic concurrency token. */
  version: number;
}

/**
 * Who gives to whom. Visible ONLY to the giver (and to everyone once revealed).
 * `id` doubles as the opaque chat thread id.
 */
export interface Assignment {
  id: AssignmentId;
  groupId: GroupId;
  giverId: UserId;
  receiverId: UserId;
  drawNumber: number;
  /** The receiver blocked the anonymous giver's messages. */
  chatBlocked: boolean;
  createdAt: Date;
}

export interface Wish {
  id: string;
  text: string;
  link: string | null;
  size: string | null;
}

export interface Wishlist {
  groupId: GroupId;
  userId: UserId;
  items: Wish[];
  updatedAt: Date;
}

/** Direction of an anonymous message inside an assignment thread. */
export type MessageDirection = 'from_giver' | 'from_receiver';

export interface ChatMessage {
  id: MessageId;
  threadId: AssignmentId;
  groupId: GroupId;
  direction: MessageDirection;
  text: string;
  createdAt: Date;
}

export interface Report {
  id: string;
  groupId: GroupId;
  threadId: AssignmentId;
  messageId: MessageId | null;
  reporterId: UserId;
  reason: string;
  createdAt: Date;
}
